import { Component, h, State } from "@stencil/core";

@Component({
  tag: "app-about",
  shadow: true,
})
export class AppAbout {
  @State() label = "app-about: click to load helper";

  private async activate() {
    const mod = await import("../../helpers/helper-about");
    this.label = mod.answer();
  }

  render() {
    return <button onClick={() => void this.activate()}>{this.label}</button>;
  }
}